import java.io.*;
import java.util.*;

public class Main {

    static class Point {
        long[] coords;

        Point(long... coords) {
            this.coords = coords;
        }

        long computeSquaredLength() {
            long total = 0;
            for (long c : coords) {
                total += c * c;
            }
            return total;
        }

        long innerProduct(Point other) {
            long sum = 0;
            for (int i = 0; i < coords.length; i++) {
                sum += coords[i] * other.coords[i];
            }
            return sum;
        }

        Point subtract(Point other) {
            long[] newCoords = new long[coords.length];
            for (int i = 0; i < coords.length; i++) {
                newCoords[i] = coords[i] - other.coords[i];
            }
            return new Point(newCoords);
        }
    }

    public static boolean validatePoint(List<Point> pts, int index) {
        Point p = pts.get(index);
        int total = pts.size();
        for (int j = 0; j < total; j++) {
            if (j == index) continue;
            for (int k = 0; k < total; k++) {
                if (k == index || k == j) continue;
                Point v1 = pts.get(j).subtract(p);
                Point v2 = pts.get(k).subtract(p);
                if (v1.innerProduct(v2) > 0) return false;
            }
        }
        return true;
    }

