            }
            points.add(new Point(coords));
        }
        List<Integer> validIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (validatePoint(points, i)) {
                validIndices.add(i + 1);
            }
        }
        System.out.println(validIndices.size());
        for (int idx : validIndices) {
            System.out.println(idx);
        }
