class Point:
    def __init__(self, *coords):
        self.coords = list(coords)

    def compute_squared_length(self):
        total = 0
        for c in self.coords:
            total += c * c
        return total

    def inner_product(self, other):
        total = 0
        for i in range(len(self.coords)):
            total += self.coords[i] * other.coords[i]
        return total

    def subtract(self, other):
        new_coords = [self.coords[i] - other.coords[i] for i in range(len(self.coords))]
        return Point(*new_coords)

def validate_point(pts, index):
    p = pts[index]
    total = len(pts)
    for j in range(total):
        if j == index:
            continue
        for k in range(total):
            if k == index or k == j:
                continue
            v1 = pts[j].subtract(p)
            v2 = pts[k].subtract(p)
            if v1.inner_product(v2) > 0:
                return False
    return True

def main():
    n = int(input())
    if n > 11:
        print(0)
        return
    points = []
    for _ in range(n):
        parts = input().split()
        coords = [int(parts[j]) for j in range(5)]
        points.append(Point(*coords))
    valid_indices = []
    for i in range(n):
        if validate_point(points, i):
            valid_indices.append(i + 1)
    print(len(valid_indices))
    for idx in valid_indices:
        print(idx)

if __name__ == "__main__":
    main()

